import{_ as t,o as a,c as i,aj as n}from"./chunks/framework.C6uXqnaX.js";const p=JSON.parse('{"title":"Extended Diagnostics","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"extended-diagnostics.md","filePath":"extended-diagnostics.md"}'),s={name:"extended-diagnostics.md"};function o(d,e,l,r,c,g){return a(),i("div",null,e[0]||(e[0]=[n(`<h1 id="extended-diagnostics" tabindex="-1">Extended Diagnostics <a class="header-anchor" href="#extended-diagnostics" aria-label="Permalink to &quot;Extended Diagnostics&quot;">​</a></h1><p>There are many coding patterns that are technically valid to the compiler or runtime, but which may have complex nuances or caveats. These patterns may not have the intended effect expected by a developer, which often leads to bugs. The Angular compiler includes &quot;extended diagnostics&quot; which identify many of these patterns, in order to warn developers about the potential issues and enforce common best practices within a codebase.</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><p>Currently, Angular supports the following extended diagnostics:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Name</th></tr></thead><tbody><tr><td style="text-align:left;"><code>NG8101</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8101"><code>invalidBananaInBox</code></a></td></tr><tr><td style="text-align:left;"><code>NG8102</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8102"><code>nullishCoalescingNotNullable</code></a></td></tr><tr><td style="text-align:left;"><code>NG8103</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8103"><code>missingControlFlowDirective</code></a></td></tr><tr><td style="text-align:left;"><code>NG8104</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8104"><code>textAttributeNotBinding</code></a></td></tr><tr><td style="text-align:left;"><code>NG8105</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8105"><code>missingNgForOfLet</code></a></td></tr><tr><td style="text-align:left;"><code>NG8106</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8106"><code>suffixNotSupported</code></a></td></tr><tr><td style="text-align:left;"><code>NG8107</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8107"><code>optionalChainNotNullable</code></a></td></tr><tr><td style="text-align:left;"><code>NG8108</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8108"><code>skipHydrationNotStatic</code></a></td></tr><tr><td style="text-align:left;"><code>NG8109</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8109"><code>interpolatedSignalNotInvoked</code></a></td></tr><tr><td style="text-align:left;"><code>NG8111</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8111"><code>uninvokedFunctionInEventBinding</code></a></td></tr><tr><td style="text-align:left;"><code>NG8112</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8112"><code>unusedLetDeclaration</code></a></td></tr><tr><td style="text-align:left;"><code>NG8113</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8113"><code>unusedStandaloneImports</code></a></td></tr><tr><td style="text-align:left;"><code>NG8114</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8114"><code>unparenthesizedNullishCoalescing</code></a></td></tr><tr><td style="text-align:left;"><code>NG8115</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8115"><code>uninvokedTrackFunction</code></a></td></tr><tr><td style="text-align:left;"><code>NG8116</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8116"><code>missingStructuralDirective</code></a></td></tr><tr><td style="text-align:left;"><code>NG8117</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8117"><code>uninvokedFunctionInTextInterpolation</code></a></td></tr><tr><td style="text-align:left;"><code>NG8119</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8119"><code>numericCssPropertyRequiresUnit</code></a></td></tr><tr><td style="text-align:left;"><code>NG8021</code></td><td style="text-align:left;"><a href="/extended-diagnostics/NG8021"><code>deferTriggerMisconfiguration</code></a></td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Extended diagnostics are warnings by default and do not block compilation. Each diagnostic can be configured as either:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error category</th><th style="text-align:left;">Effect</th></tr></thead><tbody><tr><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">Default - The compiler emits the diagnostic as a warning but does not block compilation. The compiler will still exist with status code 0, even if warnings are emitted.</td></tr><tr><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">The compiler emits the diagnostic as an error and fails the compilation. The compiler will exit with a non-zero status code if one or more errors are emitted.</td></tr><tr><td style="text-align:left;"><code>suppress</code></td><td style="text-align:left;">The compiler does <em>not</em> emit the diagnostic at all.</td></tr></tbody></table><p>Check severity can be configured as an <a href="/reference/configs/angular-compiler-options">Angular compiler option</a>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;angularCompilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;extendedDiagnostics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;checks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;invalidBananaInBox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;suppress&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;defaultCategory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>checks</code> field maps the name of individual diagnostics to their associated category. See <a href="#diagnostics">Diagnostics</a> for a complete list of extended diagnostics and the name to use for configuring them.</p><p>The <code>defaultCategory</code> field is used for any diagnostics that are not explicitly listed under <code>checks</code>. If not set, such diagnostics will be treated as <code>warning</code>.</p><p>Extended diagnostics will emit when <a href="/tools/cli/template-typecheck#strict-mode"><code>strictTemplates</code></a> is enabled. This is required to allow the compiler to better understand Angular template types and provide accurate and meaningful diagnostics.</p><h2 id="semantic-versioning" tabindex="-1">Semantic Versioning <a class="header-anchor" href="#semantic-versioning" aria-label="Permalink to &quot;Semantic Versioning&quot;">​</a></h2><p>The Angular team intends to add or enable new extended diagnostics in <strong>minor</strong> versions of Angular (see <a href="https://docs.npmjs.com/about-semantic-versioning" target="_blank" rel="noreferrer">semver</a>). This means that upgrading Angular may show new warnings in your existing codebase. This enables the team to deliver features more quickly and to make extended diagnostics more accessible to developers.</p><p>However, setting <code>&quot;defaultCategory&quot;: &quot;error&quot;</code> will promote such warnings to hard errors. This can cause a minor version upgrade to introduce compilation errors, which may be seen as a semver non-compliant breaking change. Any new diagnostics can be suppressed or demoted to warnings via the above <a href="#configuration">configuration</a>, so the impact of a new diagnostic should be minimal to projects that treat extended diagnostics as errors by default. Defaulting to error is a very powerful tool; just be aware of this semver caveat when deciding if <code>error</code> is the right default for your project.</p><h2 id="new-diagnostics" tabindex="-1">New Diagnostics <a class="header-anchor" href="#new-diagnostics" aria-label="Permalink to &quot;New Diagnostics&quot;">​</a></h2><p>The Angular team is always open to suggestions about new diagnostics that could be added. Extended diagnostics should generally:</p><ul><li>Detect a common, non-obvious developer mistake with Angular templates</li><li>Clearly articulate why this pattern can lead to bugs or unintended behavior</li><li>Suggest one or more clear solutions</li><li>Have a low, preferably zero, false-positive rate</li><li>Apply to the vast majority of Angular applications (not specific to an unofficial library)</li><li>Improve program correctness or performance (not style, that responsibility falls to a linter)</li></ul><p>If you have an idea for an extended diagnostic which fits these criteria, consider filing a <a href="https://github.com/angular/angular/issues/new?template=2-feature-request.yaml" target="_blank" rel="noreferrer">feature request</a>.</p>`,20)]))}const u=t(s,[["render",o]]);export{p as __pageData,u as default};
